const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(__dirname, 'migrations');

function runMigration() {
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory '${migrationsDir}' does not exist.`);
    process.exit(1);
  }

  try {
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files and sort them alphabetically
    const sqlFiles = files
      .filter(file => {
        const filePath = path.join(migrationsDir, file);
        return fs.statSync(filePath).isFile() && file.endsWith('.sql');
      })
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    sqlFiles.forEach(file => {
      console.log(file);
    });
  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

runMigration();

