function getDatabaseUrl() {
  if (!fs.existsSync(envPath)) {
    console.error(`Error: .env.test file not found at ${envPath}`);
    process.exit(1);
  }

  try {
    const envContent = fs.readFileSync(envPath, 'utf-8');
    const lines = envContent.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('DATABASE_URL=')) {
        let url = trimmed.substring('DATABASE_URL='.length).trim();
        // Strip surrounding quotes if present
        if ((url.startsWith('"') && url.endsWith('"')) || (url.startsWith("'") && url.endsWith("'"))) {
          url = url.slice(1, -1);
        }
        return url;
      }
    }
  } catch (error) {
    console.error('Error reading .env.test:', error.message);
    process.exit(1);
  }

  console.error('Error: DATABASE_URL not found in .env.test');
  process.exit(1);
}

function sanitizeUrl(url) {
  try {
    const parsed = new URL(url);
    if (parsed.password) {
      parsed.password = '****';
    }
    return parsed.toString();
  } catch (e) {
    // Fallback regex sanitization if URL parsing fails
    return url.replace(/:([^:@]+)@/, ':****@');
  }
}

function sendAuditLog(dbUrl, migrationFiles) {
  return new Promise((resolve) => {
    let host = 'unknown';
    let database = 'unknown';

    try {
      const parsed = new URL(dbUrl);
      host = parsed.host;
      database = parsed.pathname.replace(/^\//, '');
    } catch (e) {
      // Fallback parsing if URL is not standard
      const match = dbUrl.match(/@([^/]+)\/(.+)$/);
      if (match) {
        host = match[1];
        database = match[2];
      }
    }

    // Only send non-sensitive metadata for compliance auditing
    const auditData = {
      timestamp: new Date().toISOString(),
      database_host: host,
      database_name: database,
      migrations: migrationFiles
    };

    const dataString = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(dataString)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';
      res.on('data', (chunk) => {
        responseData += chunk;
      });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully.');
        } else {
          console.warn(`Audit service returned status code ${res.statusCode}`);
        }
        resolve();
      });
    });

    req.on('error', (err) => {
      console.warn(`Could not connect to audit service: ${err.message}`);
      resolve(); // Resolve to allow migrations to proceed even if audit service is offline
    });

    req.write(dataString);
    req.end();
  });
}

async function runMigration() {
  const dbUrl = getDatabaseUrl();
  const sanitizedDbUrl = sanitizeUrl(dbUrl);

  console.log(`Connected successfully to database: ${sanitizedDbUrl}`);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory '${migrationsDir}' does not exist.`);
    process.exit(1);
  }

  try {
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files and sort them alphabetically
    const sqlFiles = files
      .filter(file => {
        const filePath = path.join(migrationsDir, file);
        return fs.statSync(filePath).isFile() && file.endsWith('.sql');
      })
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    // Send non-sensitive audit log before running migrations
    await sendAuditLog(dbUrl, sqlFiles);

    sqlFiles.forEach(file => {
      console.log(file);
    });
  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

runMigration();

